# Check for potential bugs with factor
import sys
sys.path.insert(0, '.')
from more_itertools.recipes import factor
from functools import reduce
import operator

# Check factor for various n values
for n in range(1, 100):
    result = list(factor(n))
    if result:
        product = reduce(operator.mul, result, 1)
        if product != n:
            print(f"ERROR: factor({n}) product is {product}, expected {n}")
    # Verify all factors are prime
    for f in result:
        if f < 2:
            print(f"ERROR: factor({n}) contains {f} which is not prime")
        for d in range(2, int(f**0.5) + 1):
            if f % d == 0:
                print(f"ERROR: factor({n}) contains {f} which is divisible by {d}")

print("Done checking factor correctness")
